@namespace sv_89e5ca7e1b1d4c4fae9cbcb1d31da4f2.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemoveClick">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name</label>
        <input type="text" class="form-control" value="@Model.Company"
               @onchange="e => UpdateModel(Model with { Company = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title</label>
        <input type="text" class="form-control" value="@Model.Title"
               @onchange="e => UpdateModel(Model with { Title = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" class="form-control" value="@Model.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateModel(Model with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>

        @if (!IsCurrent)
        {
            <div class="form-group">
                <label>End Date</label>
                <input type="date" class="form-control" value="@(Model.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                       @onchange="e => UpdateModel(Model with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!) })" />
            </div>
        }
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" @onchange="e => UpdateModel(Model with { Description = e.Value?.ToString() ?? string.Empty })">@Model.Description</textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Model { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnModelChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Model.EndDate is null && Model.IsCurrent;

    private async Task UpdateModel(WorkEntryModel updated)
    {
        await OnModelChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = Model with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Model.EndDate };
        await OnModelChanged.InvokeAsync(updated);
    }

    private async Task OnRemoveClick()
    {
        await OnRemove.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

