@namespace sv_89e5ca7e1b1d4c4fae9cbcb1d31da4f2.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name <span class="required">*</span></label>
        <input type="text" class="form-control" value="@FullName"
               @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
        @if (_errors.ContainsKey("FullName"))
        {
            <span class="validation-error">@_errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label>Email <span class="required">*</span></label>
        <input type="email" class="form-control" value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
        @if (_errors.ContainsKey("Email"))
        {
            <span class="validation-error">@_errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label>Phone <span class="required">*</span></label>
        <input type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
        @if (_errors.ContainsKey("Phone"))
        {
            <span class="validation-error">@_errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label>Address <span class="required">*</span></label>
        <textarea class="form-control" rows="2" @onchange="e => Address = e.Value?.ToString() ?? string.Empty">@Address</textarea>
        @if (_errors.ContainsKey("Address"))
        {
            <span class="validation-error">@_errors["Address"]</span>
        }
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> _errors = new();
    private bool _isValidating;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            _errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            _errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            _errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            _errors["Address"] = "Address is required.";

        if (_errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            _isValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            _isValidating = false;

            if (!isValid)
            {
                _errors["Email"] = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

