@page "/apply"
@namespace sv_89e5ca7e1b1d4c4fae9cbcb1d31da4f2.Components.Pages.Apply
@using sv_89e5ca7e1b1d4c4fae9cbcb1d31da4f2.Models
@using sv_89e5ca7e1b1d4c4fae9cbcb1d31da4f2.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-wizard">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   HighestCompletedStep="_highestCompletedStep"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName"
                              Email="@_email"
                              Phone="@_phone"
                              Address="@_address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep @ref="_reviewStep"
                        FullName="@_fullName"
                        Email="@_email"
                        Phone="@_phone"
                        Address="@_address"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private int _highestCompletedStep;
    private ReviewStep? _reviewStep;

    // Step 1 data
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 data
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new()
    {
        new WorkEntryForm.WorkEntryModel()
    };

    // Step 3 data
    private List<ReferenceForm.ReferenceModel> _references = new()
    {
        new ReferenceForm.ReferenceModel(),
        new ReferenceForm.ReferenceModel()
    };

    // Step 4 data
    private string _coverLetter = string.Empty;

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        AdvanceStep();
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        AdvanceStep();
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> references)
    {
        _references = references;
        AdvanceStep();
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        AdvanceStep();
    }

    private async Task HandleSubmit()
    {
        try
        {
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());

            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var personalInfo = new PersonalInfo(_fullName, _email, _phone, _address);
            var application = new JobApplication(personalInfo, workHistory, references, _coverLetter);

            var applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _reviewStep?.ShowConfirmation(applicationId);
        }
        catch (Exception ex)
        {
            _reviewStep?.ShowError($"Submission failed: {ex.Message}");
        }
    }

    private void AdvanceStep()
    {
        _currentStep++;
        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }
}

