@namespace sv_89e5ca7e1b1d4c4fae9cbcb1d31da4f2.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemoveClick">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name</label>
        <input type="text" class="form-control" value="@Model.Company"
               @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title</label>
        <input type="text" class="form-control" value="@Model.Title"
               @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" class="form-control" value="@Model.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="OnStartDateChanged" />
        </div>

        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="OnCurrentChanged" />
                Currently working here
            </label>
        </div>

        @if (!IsCurrent)
        {
            <div class="form-group">
                <label>End Date</label>
                <input type="date" class="form-control" value="@EndDateValue"
                       @onchange="OnEndDateChanged" />
            </div>
        }
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Model.Description"
                  @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Model { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnModelChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Model.IsCurrent;
    private string EndDateValue => Model.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnModelChanged.InvokeAsync(Model with { Company = e.Value?.ToString() ?? string.Empty });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnModelChanged.InvokeAsync(Model with { Title = e.Value?.ToString() ?? string.Empty });

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        var dateStr = e.Value?.ToString();
        var date = string.IsNullOrEmpty(dateStr) ? DateTime.Today : DateTime.Parse(dateStr);
        return OnModelChanged.InvokeAsync(Model with { StartDate = date });
    }

    private Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        return OnModelChanged.InvokeAsync(Model with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Model.EndDate });
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var dateStr = e.Value?.ToString();
        DateTime? endDate = string.IsNullOrEmpty(dateStr) ? null : DateTime.Parse(dateStr);
        return OnModelChanged.InvokeAsync(Model with { EndDate = endDate });
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnModelChanged.InvokeAsync(Model with { Description = e.Value?.ToString() ?? string.Empty });

    private Task OnRemoveClick() => OnRemove.InvokeAsync();

    public record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

