    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnModelChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Model.EndDate is null && Model.IsCurrent;

    private async Task UpdateModel(WorkEntryModel updated)
    {
        await OnModelChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = Model with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Model.EndDate };
        await OnModelChanged.InvokeAsync(updated);
    }

    private async Task OnRemoveClick()
    {
        await OnRemove.InvokeAsync();
    }

    public record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

